#The_Fairie_Round-RF.rb
#A Galliard by Antony Holborne 1545 – 1602
#coded for Sonic Pi by Robin Newman, September 2020
#play using run_file "path/to/The_Farie_Round-RF.rb"
use_bpm 198
with_fx :reverb,room: 0.8, mix: 0.7 do
with_fx :level,amp: 0.95 do |v|
set :v,v
r=0.075 #release fraction
in_thread do
 at [8*6,16*6,24*6,32*6,40*6,48*6],[0.6,0.9,0.5,0.9,0.4,0.95]do |a|
   tick #count number of times "at" activated
   slide=0 #normally change volume straight away
   slide=36 if look==5 #do a crescendo rather than quick change last time
   control get(:v),amp: a,amp_slide: slide #control the volume at set times in the piece
 end
end
